// listen.mjs: node listen.mjs, then in another shell:
// ANTHROPIC_BASE_URL=http://localhost:8787 claude -p "say hi"
import { createServer } from 'node:http';
import { writeFileSync } from 'node:fs';
let n = 0;
createServer((req, res) => {
  let body = '';
  req.on('data', (c) => (body += c));
  req.on('end', () => {
    writeFileSync(`request-${++n}.json`, body);
    const r = JSON.parse(body || '{}');
    const len = (x) => JSON.stringify(x ?? '').length;
    console.log(n, r.model, { system: len(r.system), tools: len(r.tools), messages: len(r.messages) });
    res.writeHead(400).end();
  });
}).listen(8787);
